class CountdownIterator:
    def __init__(self, start):
        self.current = start

    def __iter__(self):
        return self   # an iterator is typically its own __iter__

    def __next__(self):
        if self.current <= 0:
            raise StopIteration
        value = self.current
        self.current -= 1
        return value

for n in CountdownIterator(3):
    print(n)
# 3
# 2
# 1

