class Guard:
    def __enter__(self):
        print("enter")
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        print("exit")
        return False

try:
    with Guard():
        print("inside")
        raise ValueError("boom")
except ValueError as e:
    print(f"caught: {e}")

