from typing import Optional

def find_first_negative(numbers: list[int]) -> Optional[int]:
    for n in numbers:
        if n < 0:
            return n
    return None   # explicitly documented as a possible outcome via Optional[int]

result = find_first_negative([3, 7, -2, 8])
if result is not None:
    print(f"Found: {result}")
else:
    print("No negative numbers found")

# Skipping the None check entirely still runs -- Python doesn't force you to check:
result2 = find_first_negative([1, 2, 3])
# print(result2 + 1)   # would raise TypeError: unsupported operand type(s) for +: 'NoneType' and 'int'

def hinted_total(prices: list[float]) -> float:
    return sum(prices)

def unhinted_discount(total, rate):   # no hints at all -- perfectly legal
    return total * (1 - rate)

prices = [19.99, 5.50, 12.00]
total = hinted_total(prices)          # a float, per the hint
final_price = unhinted_discount(total, 0.1)   # works fine -- unhinted params are treated as Any

print(final_price)   # 33.741

exercises.solutionCode:
from typing import Optional

def safe_divide(a: float, b: float) -> Optional[float]:
    if b == 0:
        return None
    return a / b

print(safe_divide(10, 2))   # 5.0
print(safe_divide(10, 0))   # None

result = safe_divide(10, 0)
if result is not None:
    print(f"Result: {result}")
else:
    print("Cannot divide by zero")
